// ---------------------------------------------------------------- interface sounds
// Three sounds cut from the recording the owner supplied (videoplayback.m4b), 22 kHz mono WAV, embedded as base64 so they work from any host (and file://):
//   a = a soft rising whoosh (0.67 s)   b = the bright "tching" ping (0.22 s, ~1.8 kHz)   c = a short tick (0.1 s)
// UIS wires them to the menus, the character creator, the garage, the HUD buttons and the bag: UIS.chime() is "tching, tching" (a ping and a ping a third higher).
const SFX={D:{a:'',b:'',c:''},buf:{},st:0,q:[],
  ok(){const A=window.AUD;if(!A)return false;if(!A.ok)A.start();else if(A.ctx&&A.ctx.state==='suspended')A.ctx.resume();if(!A.ok||!A.ctx)return false;if(!this.st)this.load();return true},
  load(){const c=AUD.ctx;this.st=1;for(const k of Object.keys(this.D)){try{const bin=atob(this.D[k]),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
    c.decodeAudioData(u.buffer,b=>{this.buf[k]=b;this.flush()},()=>{})}catch(e){}}},
  flush(){const q=this.q;this.q=[];const n=performance.now();for(const a of q)if(n-a[4]<900)this.play(a[0],a[1],a[2],a[3])},
  play(k,vol,rate,delay){if(!this.ok())return false;const b=this.buf[k];if(!b){this.q.push([k,vol,rate,delay,performance.now()]);return true}
    const c=AUD.ctx,s=c.createBufferSource(),g=c.createGain();s.buffer=b;if(rate)s.playbackRate.value=rate;g.gain.value=vol==null?.8:vol;s.connect(g);g.connect(AUD.sfx||AUD.master);s.start(c.currentTime+(delay||0));return true}};
const UIS={t:0,hov:null,
  chime(){SFX.play('b',.8,1,0);SFX.play('b',.7,1.26,.12)},                          // menu choice: tching, tching
  pick(){SFX.play('c',.7,1.12,0)},                                                   // a character option, a tab, a HUD button
  back(){SFX.play('c',.6,.85,0)},
  swap(){SFX.play('a',.4,1.05,0);SFX.play('b',.6,1.12,.15)},                         // the garage turntable changes car: a whoosh, then the ping as the new one settles
  whoosh(){SFX.play('a',.5,1,0)},
  go(){SFX.play('b',.8,1,0);SFX.play('b',.75,1.5,.1);SFX.play('a',.3,1.2,.05)},     // start the game / take the car out
  bag(){SFX.play('b',.5,1.35,0)},
  tick(){const n=performance.now();if(n-this.t<70)return;this.t=n;SFX.play('c',.16,1.7,0)},
  init(){if(this.done)return;this.done=true;
    const sel=e=>{const t=e.target&&e.target.closest?e.target.closest('button,#bagX'):null;return t&&!t.disabled?t:null};
    document.addEventListener('pointerdown',()=>SFX.ok(),{capture:true,once:true});     // the first touch starts the audio and decodes the sounds, so the first ping is not late
    document.addEventListener('click',e=>{const b=sel(e);if(!b)return;
      if(b.closest('#creator')){const i=b.id;if(i==='crGo')this.go();else if(i==='crBack')this.back();else if(i==='crRand'||i==='crReset')this.swap();else this.pick()}
      else if(b.closest('#menu'))this.chime();
      else if(b.closest('#bagPanel')||b.id==='bagX')this.bag();
      else if(b.closest('#actBtns,#topBtns,#gunBar,#toolTiles,#coHud')&&b.id!=='bJump'&&b.id!=='bCar'&&b.id!=='bView')this.pick()},true);
    document.addEventListener('mouseover',e=>{const b=e.target&&e.target.closest?e.target.closest('#menu button,#creator button,#garage button'):null;if(b!==this.hov){this.hov=b;if(b&&!b.disabled)this.tick()}});
    document.addEventListener('mouseout',e=>{if(!e.relatedTarget)this.hov=null})}};
UIS.init();
